// Generated by Claude Code — direkter Push-Versand an iOS-Geräte über Apples
// Push-Dienst (APNs, HTTP/2 + Token-Auth). Die native iOS-App speichert ihr
// Geräte-Token in push_tokens als "apns:prod:<hex>" bzw. "apns:dev:<hex>"
// (Debug-Builds aus Xcode nutzen die Sandbox, TestFlight/App Store Produktion).
//
// Benötigte Supabase-Secrets:
//   APNS_KEY_P8   Inhalt der .p8-Datei (Apple Developer → Keys → APNs)
//   APNS_KEY_ID   10-stellige Key ID
//   APNS_TEAM_ID  Team-ID (DVH3MYQ64A)
//   APNS_TOPIC    optional, Standard de.klangradar.native

import type { PushPayload, PushSendResult } from "./fcm.ts";

let cachedJwt: { token: string; issuedAt: number } | null = null;

function b64url(bytes: Uint8Array): string {
  let binary = "";
  for (const b of bytes) binary += String.fromCharCode(b);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

async function providerToken(): Promise<string> {
  const now = Math.floor(Date.now() / 1000);
  // Apple akzeptiert ein Token bis zu 60 Min., erneuert wird nach 50.
  if (cachedJwt && now - cachedJwt.issuedAt < 50 * 60) return cachedJwt.token;
  const p8 = Deno.env.get("APNS_KEY_P8");
  const keyId = Deno.env.get("APNS_KEY_ID");
  const teamId = Deno.env.get("APNS_TEAM_ID");
  if (!p8 || !keyId || !teamId) throw new Error("APNS_KEY_P8 / APNS_KEY_ID / APNS_TEAM_ID sind nicht gesetzt.");
  const der = Uint8Array.from(atob(p8.replace(/-----[^-]+-----/g, "").replace(/\s+/g, "")), (c) => c.charCodeAt(0));
  const key = await crypto.subtle.importKey("pkcs8", der, { name: "ECDSA", namedCurve: "P-256" }, false, ["sign"]);
  const enc = new TextEncoder();
  const unsigned = `${b64url(enc.encode(JSON.stringify({ alg: "ES256", kid: keyId })))}.${b64url(enc.encode(JSON.stringify({ iss: teamId, iat: now })))}`;
  const signature = new Uint8Array(await crypto.subtle.sign({ name: "ECDSA", hash: "SHA-256" }, key, enc.encode(unsigned)));
  cachedJwt = { token: `${unsigned}.${b64url(signature)}`, issuedAt: now };
  return cachedJwt.token;
}

export function isApnsToken(token: string): boolean {
  return token.startsWith("apns:");
}

export async function sendApnsToTokens(tokens: string[], payload: PushPayload): Promise<PushSendResult[]> {
  if (tokens.length === 0) return [];
  const topic = Deno.env.get("APNS_TOPIC") ?? "de.klangradar.native";
  let jwt: string;
  try {
    jwt = await providerToken();
  } catch (err) {
    const error = err instanceof Error ? err.message : String(err);
    return tokens.map((token) => ({ token, ok: false, invalidToken: false, error }));
  }
  const body = JSON.stringify({
    aps: { alert: { title: payload.title, body: payload.body }, sound: "default" },
    ...(payload.data ?? {}),
  });
  const results: PushSendResult[] = [];
  for (const token of tokens) {
    const [, environment, deviceToken] = token.split(":");
    const host = environment === "dev" ? "api.sandbox.push.apple.com" : "api.push.apple.com";
    try {
      const res = await fetch(`https://${host}/3/device/${deviceToken}`, {
        method: "POST",
        headers: {
          authorization: `bearer ${jwt}`,
          "apns-topic": topic,
          "apns-push-type": "alert",
          "apns-priority": "10",
          "content-type": "application/json",
        },
        body,
      });
      if (res.ok) {
        results.push({ token, ok: true, invalidToken: false });
      } else {
        const errText = await res.text();
        // 410 Unregistered / BadDeviceToken: App gelöscht oder Token falsch.
        const invalidToken = res.status === 410 || /BadDeviceToken|Unregistered|DeviceTokenNotForTopic/.test(errText);
        results.push({ token, ok: false, invalidToken, error: errText });
      }
    } catch (err) {
      results.push({ token, ok: false, invalidToken: false, error: err instanceof Error ? err.message : String(err) });
    }
  }
  return results;
}
